import pandas as pd
_df0 = (
    Table_0.copy()
    .assign(**{
        'Students with 2 or More Suspensions or Removals': Table_0['Students with 2 or More Suspensions or Removals']
            .replace(['*'], pd.NA)
    })
    .dropna(subset=['Students with 2 or More Suspensions or Removals'])
    .assign(**{
        'Students with 2 or More Suspensions or Removals': lambda x: pd.to_numeric(
            x['Students with 2 or More Suspensions or Removals'], errors='coerce')
    })
)
_df1 = (
    Table_1.copy()
    .assign(**{
        'TOTAL REMOVALS/SUSPENSIONS': Table_1['TOTAL REMOVALS/SUSPENSIONS'].replace(['R'], pd.NA)
    })
    .dropna(subset=['TOTAL REMOVALS/SUSPENSIONS'])
    .assign(**{
        'TOTAL REMOVALS/SUSPENSIONS': lambda x: pd.to_numeric(x['TOTAL REMOVALS/SUSPENSIONS'], errors='coerce'),
        'Administrative_District_Code': lambda x: pd.to_numeric(x['Administrative_District_Code'], errors='coerce')
    })
)
_df2 = (
    Table_2.copy()
    .assign(**{
        'SY1718 TOTAL REMOVALS/SUSPENSIONS': Table_2['SY1718 TOTAL REMOVALS/SUSPENSIONS'].replace(['R'], pd.NA)
    })
    .dropna(subset=['SY1718 TOTAL REMOVALS/SUSPENSIONS'])
    .assign(**{
        'SY1718 TOTAL REMOVALS/SUSPENSIONS': lambda x: pd.to_numeric(x['SY1718 TOTAL REMOVALS/SUSPENSIONS'], errors='coerce')
    })
)
merged = (
    _df0.merge(_df2, on='DBN', suffixes=('_0', '_2'))
        .merge(_df1, left_on='Administrative District', right_on='Administrative_District_Code', suffixes=('', '_1'))
)
merged = merged.assign(has_removal=lambda x: x['SY1718 TOTAL REMOVALS/SUSPENSIONS'] > 0)
result = (
    merged
    .groupby(['LOCATION CATEGORY', 'Demographic Category'])
    .apply(lambda g: pd.Series({
        'total_removals_2017_18': g['SY1718 TOTAL REMOVALS/SUSPENSIONS'].sum(),
        'schools_with_removal': g.loc[g['has_removal'], 'DBN'].nunique(),
        'district_removals_2020_21': g.drop_duplicates('Administrative District')['TOTAL REMOVALS/SUSPENSIONS'].sum()
    }))
    .reset_index()
)

