import pandas as pd
susp_df = (
    Table_0[Table_0['School Year'] == '2016-2017']
    .assign(**{
        'Students with 2 or More Suspensions or Removals': Table_0['Students with 2 or More Suspensions or Removals']
            .replace('*', pd.NA)
    })
    .dropna(subset=['Students with 2 or More Suspensions or Removals'])
    .assign(**{
        'Students with 2 or More Suspensions or Removals': lambda df: pd.to_numeric(
            df['Students with 2 or More Suspensions or Removals'], errors='coerce')
    })
)
susp_agg = (
    susp_df.groupby('Administrative District', as_index=False)
    .agg(susp_total=('Students with 2 or More Suspensions or Removals', 'sum'))
)
black_df = (
    Table_1.rename(columns={'ADMINISTRATIVE DISTRICT': 'Administrative District'})
    .assign(**{
        'Black REMOVALS': lambda df: df['Black REMOVALS'].replace('R', pd.NA)
    })
    .assign(**{
        'Black REMOVALS': lambda df: df['Black REMOVALS'].fillna(0)
    })
    .assign(**{
        'Black REMOVALS': lambda df: pd.to_numeric(df['Black REMOVALS'], errors='coerce')
    })
)
black_agg = (
    black_df.groupby('Administrative District', as_index=False)
    .agg(black_total=('Black REMOVALS', 'sum'))
)
result = (
    susp_agg.merge(black_agg, on='Administrative District', how='outer')
    .fillna({'susp_total': 0, 'black_total': 0})
    .assign(combined_total=lambda df: df['susp_total'] + df['black_total'])
    .sort_values('combined_total', ascending=False)
    .head(5)
)

df = (
    Table_0.copy()
    .replace({
        'Percent Scoring 80 or Above': {
            'na': pd.NA,
            'NA': pd.NA,
            's': pd.NA
        }
    })
    .dropna(subset=['Percent Scoring 80 or Above'])
    .assign(**{
        'Percent Scoring 80 or Above': lambda x: pd.to_numeric(x['Percent Scoring 80 or Above'], errors='coerce')
    })
    .loc[lambda x: x['Regents Exam'].str.contains('English', case=False, na=False)
                & x['Year'].isin([2015, 2019])
                & (x['School Level'].str.lower() == 'high school')]
)
pivot = (
    df.pivot_table(
        index=['School DBN', 'School Name'],
        columns='Year',
        values='Percent Scoring 80 or Above',
        aggfunc='mean'
    )
    .reset_index()
    .rename(columns={2015: 'p2015', 2019: 'p2019'})
)
pivot['increase'] = pivot['p2019'] - pivot['p2015']
result = (
    pivot.sort_values('increase', ascending=False)
    .head(3)[['School DBN', 'School Name', 'increase']]
)

